@startuml

class Bettor {
  + bettorId : int
  + name : string
  + contactInfo : string
}

class Race {
  + raceId : int
  + raceName : string
  + startTime : datetime
}

class Runner {
  + runnerId : int
  + horseName : string
  + horseAge : int
}

class Jockey {
  + jockeyId : int
  + name : string
  + nationality : string
}

class Bet {
  + betId : int
  + amount : double
  + odds : double
}

Bettor "1" -- "0..*" Bet : places
Race "1" *-- "1..*" Runner
Runner "1" -- "1" Jockey : riddenBy
Bet "*" -- "1" Race : refersTo
Bet "*" -- "1" Runner : refersTo

@enduml

